fn solve(n: i8) -> i8 {
    // For positive n, the alternating sum -1 + 2 - 3 + 4 ... ± n
    // has the closed‐form:
    //   if n is even:  n/2
    //   if n is odd:   (n/2) - n
    //
    // Since n > 0, integer division n/2 is just floor(n/2).
    if n % 2 == 0 {
        n / 2
    } else {
        n / 2 - n
    }
}

#[cfg(test)]
mod tests {
    use super::solve;

    #[test]
    fn test_small() {
        assert_eq!(solve(1), -1); // -1
        assert_eq!(solve(2),  1); // -1 + 2 = 1
        assert_eq!(solve(3), -2); // -1 + 2 - 3 = -2
        assert_eq!(solve(4),  2); // -1 + 2 - 3 + 4 = 2
        assert_eq!(solve(5), -3); // -1 + 2 - 3 + 4 - 5 = -3
    }

    #[test]
    fn test_even_and_odd() {
        for n in 1..=20 {
            let mut sum = 0i8;
            for i in 1..=n {
                if i % 2 == 0 {
                    sum += i;
                } else {
                    sum -= i;
                }
            }
            assert_eq!(solve(n), sum);
        }
    }
}